class Solution { public List<List<Integer>> findDifference(int[] nums1,int[] nums2){Set<Integer> first=new TreeSet<>(),second=new TreeSet<>();for(int value:nums1)first.add(value);for(int value:nums2)second.add(value);List<Integer> onlyFirst=new ArrayList<>(),onlySecond=new ArrayList<>();for(int value:first)if(!second.contains(value))onlyFirst.add(value);for(int value:second)if(!first.contains(value))onlySecond.add(value);return Arrays.asList(onlyFirst,onlySecond);} }
